import base64
import pickle


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded pickle cookie string.

    Args:
        encoded_prefs: A base64-encoded pickle string containing user preferences

    Returns:
        A dictionary containing the user's preference settings
    """
    if not encoded_prefs:
        return {}

    try:
        # Decode the base64 string
        decoded_data = base64.b64decode(encoded_prefs)

        # Deserialize the pickle object
        preferences = pickle.loads(decoded_data)

        # Ensure we return a dictionary
        if not isinstance(preferences, dict):
            return {}

        return preferences
    except (pickle.UnpicklingError, ValueError, TypeError, EOFError):
        # Return empty dict on any decoding/parsing error
        return {}

