import base64
import pickle
import logging

logger = logging.getLogger(__name__)


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded and pickled cookie string.

    Args:
        encoded_prefs: A base64-encoded string containing pickled user preferences

    Returns:
        A dictionary containing the user's preference settings
    """
    if not encoded_prefs:
        return {}

    try:
        # Decode the base64 string
        decoded_data = base64.b64decode(encoded_prefs)

        # Deserialize the preferences object using pickle
        preferences = pickle.loads(decoded_data)

        # Validate that the result is a dictionary
        if not isinstance(preferences, dict):
            logger.warning("Deserialized preferences is not a dictionary, returning empty dict")
            return {}

        return preferences

    except (base64.binascii.Error, pickle.UnpicklingError) as e:
        logger.error(f"Failed to decode preferences from cookie: {e}")
        return {}
    except Exception as e:
        logger.error(f"Unexpected error decoding preferences: {e}")
        return {}

